/**
 * Jinx Hatter + Legion: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Hatter
 * Wiki: https://wiki.bloodontheclocktower.com/Legion
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L117). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/ability.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { allEvilBecomeTests, scriptOf } from './legion.test-support.ts';

describe('Hatter + Legion jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'hatter', 'legion');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('hatter')?.name).toBe('Hatter');
		expect(data.byId.get('legion')?.name).toBe('Legion');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['hatter', 'legion'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['hatter'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['legion'])).not.toContain(jinx);
	});

	it('is data in both rules', () => {
		expect(jinxRulesBetween('hatter', 'legion', committedCharacters())).toEqual({
			patch: { when: ['partner-in-play'], parts: { impairs: { self: { reason: 'no-ability' } } } },
			allEvilBecome: {}
		});
	});

	allEvilBecomeTests('hatter');

	describe('with Legion in play the Hatter has no ability', () => {
		const script = scriptOf(['hatter', 'legion', 'imp', 'chef', 'empath', 'monk']);
		const base = scenario(['legion', 'legion', 'legion', 'hatter', 'chef', 'empath'], {
			script
		});

		it('takes the Hatter ability while Legion is in play, even dead', () => {
			// Wiki: "If Legion is in play, the Hatter has no ability."
			const state = abilityState(base.game, base.seat('hatter'), base.characters);
			expect(state.works).toBe(false);
			expect(state.impairments.map((i) => [i.reason, i.source.characterId])).toEqual([
				['no-ability', 'legion']
			]);
			const dead = base.dies('hatter');
			expect(abilityState(dead.game, dead.seat('hatter'), dead.characters).works).toBe(false);
			const none = scenario(['imp', 'hatter', 'chef', 'empath', 'monk'], { script });
			expect(abilityState(none.game, none.seat('hatter'), none.characters).works).toBe(true);
		});

		it('is not told, unlike the Engineer', () => {
			// Wiki: "If Legion is in play, the Hatter has no ability."
			const s = base.dies('hatter');
			expect(
				nightStepAlerts(s.game, 'hatter', s.characters).some((a) => a.kind === 'learns-no-ability')
			).toBe(false);
		});
	});
});
